import { useState, useEffect } from 'react';
import axios from 'axios';

export default function Home() {
  const [stats, setStats] = useState({
    totalStudents: '--',
    totalQuizzes: '--',
    totalQuestions: '--'
  });
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) throw new Error('No token');

        const response = await axios.get('http://localhost:5000/api/admin/stats', {
          headers: { Authorization: `Bearer ${token}` }
        });

        setStats(response.data);
        setError('');

        // Fetch leaderboard
        const leaderboardRes = await axios.get('http://localhost:5000/api/admin/leaderboard', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setLeaderboard(leaderboardRes.data);


      } catch (err) {
        console.error('Fetch stats failed:', err);
        setError('Failed to load stats. Check console for details.');
        setStats({ totalStudents: '0', totalQuizzes: '0', totalQuestions: '0' });
      }
    };

    fetchStats();
  }, []);

  return (
    <div>
      <h1 className="mb-4"></h1>
      
      {error && (
        <div className="alert alert-danger mb-4">{error}</div>
      )}

      <div className="row">
        {/* Students Card */}
        <div className="col-md-4 mb-4">
          <div className="card border-left-primary shadow h-100 py-2">
            <div className="card-body">
              <div className="row no-gutters align-items-center">
                <div className="col mr-2">
                  <div className="text-xs font-weight-bold text-primary text-uppercase mb-1">
                    Total Students
                  </div>
                  <div className="h5 mb-0 font-weight-bold text-gray-800">
                    {stats.totalStudents}
                  </div>
                </div>
                <div className="col-auto">
                  <i className="fas fa-user fa-2x text-gray-300"></i>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Courses Card */}
        <div className="col-md-4 mb-4">
          <div className="card border-left-success shadow h-100 py-2">
            <div className="card-body">
              <div className="row no-gutters align-items-center">
                <div className="col mr-2">
                  <div className="text-xs font-weight-bold text-success text-uppercase mb-1">
                    Total Courses
                  </div>
                  <div className="h5 mb-0 font-weight-bold text-gray-800">
                    {stats.totalQuizzes}
                  </div>
                </div>
                <div className="col-auto">
                  <i className="fas fa-book fa-2x text-gray-300"></i>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Questions Card */}
        <div className="col-md-4 mb-4">
          <div className="card border-left-info shadow h-100 py-2">
            <div className="card-body">
              <div className="row no-gutters align-items-center">
                <div className="col mr-2">
                  <div className="text-xs font-weight-bold text-info text-uppercase mb-1">
                    Total Questions
                  </div>
                  <div className="h5 mb-0 font-weight-bold text-gray-800">
                    {stats.totalQuestions}
                  </div>
                </div>
                <div className="col-auto">
                  <i className="fas fa-question fa-2x text-gray-300"></i>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
